package org.slavicmyths.serpenthill;
import java.util.*;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.coordinates.BlockPosArgument;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.server.level.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.structure.*;
import net.minecraft.world.level.levelgen.structure.pieces.PiecesContainer;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import com.mojang.brigadier.arguments.StringArgumentType;
@EventBusSubscriber(modid="slavicmyths")
public final class HillCommands {
 private static final Map<UUID,HillPlan> plans=new HashMap<>();
 public static void register(org.slavicmyths.commands.CommandTree tree){tree.add(Commands.literal("slavicmyths").then(Commands.literal("generate_serpent_hill").requires(s->s.hasPermission(2)).executes(c->start(c.getSource(),BlockPos.containing(c.getSource().getPosition()).below(12),Rotation.NONE)).then(Commands.argument("pos",BlockPosArgument.blockPos()).executes(c->start(c.getSource(),BlockPosArgument.getBlockPos(c,"pos"),Rotation.NONE)).then(Commands.argument("rotation",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(List.of("none","clockwise_90","clockwise_180","counterclockwise_90"),b)).executes(c->{Rotation r;try{r=Rotation.valueOf(StringArgumentType.getString(c,"rotation").toUpperCase(java.util.Locale.ROOT));}catch(IllegalArgumentException bad){c.getSource().sendFailure(HillContent.text("rotation"));return 0;}return start(c.getSource(),BlockPosArgument.getBlockPos(c,"pos"),r);})))));}
 private static int start(CommandSourceStack source,BlockPos requested,Rotation r){var w=source.getLevel();if(w.dimension()!=Level.OVERWORLD){source.sendFailure(HillContent.text("overworld_only"));return 0;}if(w.getMaxBuildHeight()-w.getMinBuildHeight()<HillRules.HEIGHT){source.sendFailure(HillContent.text("height"));return 0;}var d=HillWorld.get(w);if(!d.jobs().isEmpty()){source.sendFailure(HillContent.text("busy"));return 0;}int y=HillRules.base(requested.getY(),w.getMinBuildHeight(),w.getMaxBuildHeight(),(int)source.getPosition().y-12);var origin=HillGeometry.origin(new BlockPos(requested.getX(),y,requested.getZ()),r);var bounds=HillGeometry.bounds(origin,r);if(!w.getWorldBorder().isWithinBounds(new BlockPos(bounds.minX(),y,bounds.minZ()))||!w.getWorldBorder().isWithinBounds(new BlockPos(bounds.maxX(),bounds.maxY(),bounds.maxZ()))){source.sendFailure(HillContent.text("border"));return 0;}var type=w.registryAccess().registryOrThrow(Registries.STRUCTURE).get(HillContent.id("serpent_hill"));if(type==null){source.sendFailure(HillContent.text("missing_structure"));return 0;}UUID id=UUID.randomUUID();long seed=w.random.nextLong();var piece=new SerpentHillPiece(origin,r,seed,id);var owner=new ChunkPos(origin.offset(new BlockPos(64,0,64).rotate(r)));var chunk=w.getChunk(owner.x,owner.z);var old=chunk.getStartForStructure(type);if(old!=null&&old.isValid()){source.sendFailure(HillContent.text("occupied"));return 0;}d.ensure(id,origin,r,seed);d.enqueue(id);d.row(id).putLong("Owner",owner.toLong());chunk.setStartForStructure(type,new StructureStart(type,owner,0,new PiecesContainer(List.of(piece))));chunk.setUnsaved(true);w.getServer().overworld().getDataStorage().save();source.sendSuccess(()->HillContent.text("queued",bounds.minX(),y,bounds.minZ(),id.toString()),true);return 1;}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){var w=event.getServer().overworld();if(w==null)return;var d=HillWorld.get(w);if(d.jobs().isEmpty()){plans.clear();return;}UUID id=d.jobs().iterator().next();var n=d.row(id);var origin=BlockPos.of(n.getLong("Origin"));var r=Rotation.valueOf(n.getString("Rotation"));var plan=plans.computeIfAbsent(id,key->new HillPlan(n.getLong("Seed")));int cursor=n.getInt("Cursor"),end=Math.min(128*128*144,cursor+HillRules.BUILD_BUDGET);var type=w.registryAccess().registryOrThrow(Registries.STRUCTURE).get(HillContent.id("serpent_hill"));for(;cursor<end;cursor++){int tile=cursor/(256*144),within=cursor%(256*144),x=tile/8*16+within/(16*144),z=tile%8*16+(within/144)%16,y=within%144;if(!plan.authored(x,z))continue;var at=origin.offset(new BlockPos(x,y,z).rotate(r));if(at.getY()<w.getMinBuildHeight()||at.getY()>=w.getMaxBuildHeight())continue;if(!w.hasChunkAt(at))w.getChunk(at.getX()>>4,at.getZ()>>4);if(y==0&&type!=null){var c=w.getChunk(at.getX()>>4,at.getZ()>>4);c.addReferenceForStructure(type,n.getLong("Owner"));c.setUnsaved(true);}if(w.getBlockState(at).is(Blocks.BEDROCK))continue;var state=HillContent.palette.state(plan.state(x,y,z)).rotate(r);if(!w.getBlockState(at).equals(state))w.setBlock(at,state,2);if(state.is(Blocks.CHEST)&&w.getBlockEntity(at) instanceof net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity chest){var seen=n.getCompound("SeededChests");String token=at.asLong()+"";if(!seen.getBoolean(token)){chest.setLootTable(net.minecraft.resources.ResourceKey.create(Registries.LOOT_TABLE,HillContent.id("chests/serpent_fortress")),id.getMostSignificantBits()^at.asLong());seen.putBoolean(token,true);n.put("SeededChests",seen);}}}
  n.putInt("Cursor",cursor);d.setDirty();if(cursor%(256*144)==0)w.getServer().overworld().getDataStorage().save();if(cursor==128*128*144){d.finish(id);plans.remove(id);org.slavicmyths.gorynych.GorynychWorld.ensure(w,id);w.getServer().overworld().getDataStorage().save();w.getServer().getPlayerList().broadcastSystemMessage(HillContent.text("complete",id.toString()),false);w.playSound(null,origin.offset(new BlockPos(60,13,114).rotate(r)),HillContent.SOUNDS.get("raised").get(),net.minecraft.sounds.SoundSource.BLOCKS,.5f,1);}
 }
 private HillCommands(){}
}
